      en: ["Located in Al-Fashir, the capital of North Darfur", "Significantly expanded under Sultan Ali Dinar (1898–1916)", "Constructed using traditional local brickwork", "The most important Islamic landmark in the Darfur region", "Primary spiritual center for western Sudan", "Symbolizes the historical independence of the Darfur Sultanate"],
