      en: ["Burial site of Muhammad Ahmad al-Mahdi", "Original 1885 structure was destroyed in 1898", "Current dome was completed in 1947", "Features a distinctive silver-colored conical dome", "Spiritual center for the Ansar religious movement", "Stands approximately 25 meters high"],
      es: ["Mausoleo histórico de Muhammad Ahmad en Omdurmán.", "Situado en el estado del noreste de África, Sudán.", "Región caracterizada por el Nilo y el desierto de Nubia.", "Clima predominantemente cálido y seco, con zonas desérticas y de Sahel."],
      pt: ["Mausoléu histórico de Muhammad Ahmad em Ondurmã.", "Localizado no estado do nordeste de África, o Sudão.", "Região marcada pelo Nilo e pelo deserto da Núbia.", "Clima predominantemente quente e seco, com zonas desérticas e do Sahel."],
      fr: ["Mausolée historique de Muhammad Ahmad à Omdourman.", "Situé dans l'État du nord-est de l'Afrique, le Soudan.", "Région marquée par le Nil et le désert de Nubie.", "Climat principalement chaud et sec, avec des zones désertiques et sahéliennes."],
