      de: "Eine der ältesten Stahlbrücken im Sudan, die Omdurman mit der Hauptstadt Khartum verbindet und täglich von Tausenden Pendlern genutzt wird.",
      hu: "Szudán egyik legrégebbi acélhídja, amely Omdurmánt köti össze a fővárossal, Kartúmmal, és naponta ingázók ezrei használják.",
      ro: "Unul dintre cele mai vechi poduri de oțel din Sudan, care leagă Omdurman de capitala Khartoum și este folosit zilnic de mii de navetiști.",
      en: "One of the oldest steel bridges in Sudan, connecting Omdurman with the capital Khartoum and used by thousands of commuters daily.",
