      fr: ["Temple égyptien bien conservé d'Amenhotep III.", "Situé dans l'État du nord-est de l'Afrique, le Soudan.", "Région caractérisée par le Nil et le désert de Nubie.", "Climat majoritairement chaud et sec, avec des zones désertiques et sahéliennes."],
